select 

from CHB_MONTH_ASSET_POSITION
where POSUUID = #{posuuid,jdbcType=CHAR}

select sum(POSITION.ASSETVALUE_A) ASSETVALUE_A, sum(POSITION.ASSETVALUE_B) ASSETVALUE_B, POSITION.ASSETTYPE, /*行业分类改造*/ case when POSITION.ASSETTYPE2 in ('1201','1210') then ASSETINFO.INDUSTRY_SHARES when POSITION.ASSETTYPE2 in ('1202','1203','1204','1205','1206','1207','1208','1209','2201','2202','2299','1299') then nvl(ASSETINFO.PRO_INDUSTRY,ASSETINFO.INDUSTRY_PBC) when POSITION.ASSETTYPE2 in ('2101') then ASSETINFO.INDUSTRY when POSITION.ASSETTYPE2 in ('DRC1107') then '10' else null end INDUSTRY1, /*行业分类改造*/ POSITION.IN_ASSET_TYPE, POSITION.PPPFLAG, POSITION.MONIT_TYPE, POSITION.MANAGE_TYPE, POSITION.IS_GOVERN_FUND1, POSITION.PRIVATEFUND_FLAG, POSITION.PRIVATEPRD_FLAG, POSITION.BONDTOSTOCK_FLAG, POSITION.RATING,POSITION.ASSETTYPE2,ASSETINFO.ASSET_TYPE3, ASSETINFO.BANK_SEC_CAPITAL, ASSETINFO.BANK_SEC_PERPETUAL, ASSETINFO.BANK_SEC_PREFER, di.institution_code ORGID, ASSETINFO.ASSET_CODE /*G06改造新加字段*/ ASSETINFO.BANK_SEC_ZXZQ, ASSETINFO.IS_BZHPJ, ASSETINFO.ISUNLISTED, ASSETINFO.IS_FBZB, ASSETINFO.BANK_SEC_KZZQ, POSITION.IS_FHXGCP, POSITION.OLD_ASSET_CODE /*G06改造新加字段*/ from CHB_MONTH_ASSET_POSITION POSITION LEFT JOIN CHB_ASSET_INFO ASSETINFO ON ASSETINFO.ASSET_CODE = POSITION.ASSET_CODE and ASSETINFO.status in('E','M') left join (select distinct di.business_id finprod_market_id,di.institution_code from DATA_AUTH_NOTIFY_INST di where di.model_type = '02' AND DI.DATA_TYPE= 'PTL01' ) di on di.finprod_market_id = POSITION.PROD_ID where to_char(POSITION.ENDDATE, 'yyyy-MM-dd') >= #{startDate,jdbcType=VARCHAR} and to_char(POSITION.ENDDATE, 'yyyy-MM-dd') <= #{endDate,jdbcType=VARCHAR}
and POSITION.PROD_ID in
null) OR POSITION.PROD_ID in (
#{prodid}
group by POSITION.ASSETTYPE, nvl(POSITION.INDUSTRY1,'NULL'), POSITION.IN_ASSET_TYPE, POSITION.PPPFLAG, POSITION.MONIT_TYPE, POSITION.MANAGE_TYPE, POSITION.IS_GOVERN_FUND1, POSITION.PRIVATEFUND_FLAG, POSITION.PRIVATEPRD_FLAG, POSITION.BONDTOSTOCK_FLAG, POSITION.RATING, POSITION.ASSETTYPE2,ASSETINFO.ASSET_TYPE3, ASSETINFO.BANK_SEC_CAPITAL, ASSETINFO.BANK_SEC_PERPETUAL, ASSETINFO.BANK_SEC_PREFER, di.institution_code, /*G06改造新加字段*/ ASSETINFO.BANK_SEC_ZXZQ, ASSETINFO.IS_BZHPJ, ASSETINFO.ISUNLISTED ,ASSETINFO.IS_FBZB ,ASSETINFO.BANK_SEC_KZZQ /*G06改造新加字段*/ ,ASSETINFO.INDUSTRY_SHARES ,ASSETINFO.PRO_INDUSTRY ,ASSETINFO.INDUSTRY_PBC ,ASSETINFO.ASSET_CODE ,ASSETINFO.INDUSTRY ,POSITION.ASSETTYPE2 ,POSITION.IS_FHXGCP

select POSITION.ASSETVALUE_A ASSETVALUE_A, POSITION.ASSETVALUE_B ASSETVALUE_B, POSITION.ASSETTYPE, /*行业分类改造*/ case when POSITION.ASSETTYPE2 in ('1201','1210') then ASSETINFO.INDUSTRY_SHARES when POSITION.ASSETTYPE2 in ('1202','1203','1204','1205','1206','1207','1208','1209','2201','2202','2299','1299') then nvl(ASSETINFO.PRO_INDUSTRY,ASSETINFO.INDUSTRY_PBC) when POSITION.ASSETTYPE2 in ('2101') then ASSETINFO.INDUSTRY when POSITION.ASSETTYPE2 in ('DRC1107') then '10' else null end INDUSTRY1, /*行业分类改造*/ POSITION.IN_ASSET_TYPE, POSITION.PPPFLAG, POSITION.MONIT_TYPE, POSITION.MANAGE_TYPE, POSITION.IS_GOVERN_FUND1, POSITION.PRIVATEFUND_FLAG, POSITION.PRIVATEPRD_FLAG, POSITION.BONDTOSTOCK_FLAG, POSITION.RATING,POSITION.ASSETTYPE2,ASSETINFO.ASSET_TYPE3, ASSETINFO.BANK_SEC_CAPITAL, ASSETINFO.BANK_SEC_PERPETUAL, ASSETINFO.BANK_SEC_PREFER, di.institution_code ORGID, ASSETINFO.ASSET_CODE, POSITION.PROD_ID, /*G06改造新加字段*/ ASSETINFO.BANK_SEC_ZXZQ, ASSETINFO.IS_BZHPJ, ASSETINFO.ISUNLISTED, ASSETINFO.IS_FBZB, ASSETINFO.BANK_SEC_KZZQ, POSITION.IS_FHXGCP, POSITION.OLD_ASSET_CODE, ASSETINFO.BANK_CAPITAL, ASSETINFO.SHARES_TYPE /*G06改造新加字段*/ from CHB_MONTH_ASSET_POSITION POSITION LEFT JOIN CHB_ASSET_INFO ASSETINFO ON ASSETINFO.ASSET_CODE = POSITION.ASSET_CODE and ASSETINFO.status in('E','M') left join (select distinct di.business_id finprod_market_id,di.institution_code from DATA_AUTH_NOTIFY_INST di where di.model_type = '02' AND DI.DATA_TYPE= 'PTL01' ) di on di.finprod_market_id = POSITION.PROD_ID where to_char(POSITION.ENDDATE, 'yyyy-MM-dd') >= #{startDate,jdbcType=VARCHAR} and to_char(POSITION.ENDDATE, 'yyyy-MM-dd') <= #{endDate,jdbcType=VARCHAR}
and POSITION.PROD_ID in
null) OR POSITION.PROD_ID in (
#{prodid}

select #{bookdate,jdbcType=DATE} bookdate ,#{enddate,jdbcType=DATE} enddate ,pos.INVEST_VARIETY ,pos.trade_type ,pos.IS_UNDER_TRADE ,pos.ASSET_CODE ,pos.PROD_ID ,pos.chl_id chlid ,pos.CCY ,decode(pos.ASSET_CODE,'REMAININGCASH','01',info.asset_type) assettype
,case when info.asset_type2 = '1107' and info.org_asset_type2='D01' then 'DRC1107'/*同业借款*/ else decode(pos.ASSET_CODE,'REMAININGCASH','1001',info.ASSET_TYPE2) end assettype2 ,nvl(nvl(info.PRO_INDUSTRY,info.INDUSTRY1),info.INDUSTRY_SHARES) INDUSTRY1 /*所属行业*/ ,info.IN_ASSET_TYPE IN_ASSET_TYPE /*行业一级分类*/ ,sum(pos.accuamt) ASSETVALUE_A /*穿透前资产价值*/ ,sum(decode(pos.trade_type,'05',pos.accuqty,null)) ASSETVALUE_B /*穿透后资产价值*/ ,nvl(bestRatingZx.GRADERESULT,bestRatingZt.GRADERESULT) rating/*债券评级*/ ,decode(info.PRIVATE_FLAG,'01','01',null) MONIT_TYPE ,decode(info.PPPFLAG,'01','01',null) PPPFLAG ,decode(info.IS_GOVERN_FUND,'01','01',null) IS_GOVERN_FUND1 ,decode(info.PRIVATEFUND_FLAG,'01','01',null) PRIVATEFUND_FLAG ,decode(info.PRIVATEPRD_FLAG,'01','01',null) PRIVATEPRD_FLAG ,decode(info.BONDTOSTOCK_FLAG,'01','01',null) BONDTOSTOCK_FLAG ,info.MANAGE_TYPE MANAGE_TYPE /*管理方式*/ ,prd.IS_FHXGCP /**是否合新规*/ from CHB_ASSET_POSITION pos left join CHB_ASSET_INFO info on pos.ASSET_CODE=info.ASSET_CODE and info.status !='D' left join CHB_PRD_BASEINFO prd on prd.PROD_ID=pos.PROD_ID and prd.status !='D'
left join ( select t.OCODE as OCODE,t.GRADERESULT as GRADERESULT FROM( SELECT TEMP.GRADERESULT as GRADERESULT, TEMP.OCODE AS OCODE, rank() over (partition by TEMP.OCODE order by rownum) rk FROM (
AND OTYPE = '02'
)
${getProductRatingOrderSqlByZx}
