${getProductRatingOrderSqlByZt}
)t where t.rk = '1' )bestRatingZt on bestRatingZt.OCODE = info.CHB_ISSUER_ID where 1=1 and prd.PROFIT_TYPE='03' /****资产负债表中1.9.5统计错误***/ and (info.PBC_ASSET_TYPE3 NOT IN('J03','J04') or info.PBC_ASSET_TYPE3 is null) and pos.trade_type in ('01','02','05') /*直投交易,通道交易,资管计划交易*/ and pos.cDATE =#{enddate,jdbcType=DATE}
and pos.PROD_ID in
null) OR pos.PROD_ID in (
#{prodid}
group by #{bookdate,jdbcType=DATE},#{enddate,jdbcType=DATE}, pos.INVEST_VARIETY,pos.trade_type,pos.IS_UNDER_TRADE, pos.ASSET_CODE, pos.PROD_ID, pos.chl_id, pos.CCY, decode(pos.ASSET_CODE,'REMAININGCASH','01',info.asset_type),
case when info.asset_type2 = '1107' and info.org_asset_type2='D01' then 'DRC1107' else decode(pos.ASSET_CODE,'REMAININGCASH','1001',info.ASSET_TYPE2) end, nvl(nvl(info.PRO_INDUSTRY,info.INDUSTRY1),info.INDUSTRY_SHARES),info.IN_ASSET_TYPE, null,nvl(bestRatingZx.GRADERESULT,bestRatingZt.GRADERESULT), decode(info.PRIVATE_FLAG,'01','01',null), decode(info.PPPFLAG,'01','01',null), decode(info.IS_GOVERN_FUND,'01','01',null), decode(info.PRIVATEFUND_FLAG,'01','01',null), decode(info.PRIVATEPRD_FLAG,'01','01',null), decode(info.BONDTOSTOCK_FLAG,'01','01',null), info.MANAGE_TYPE,prd.IS_FHXGCP

